<script setup>
import { Download,FileJson,FileSpreadsheet,ExternalLink } from '@lucide/vue'
import { useCatalog } from '../composables/catalog.js'
import { exportTsv,downloadBlob,sampleColumns } from '../utils/data.js'
import PageTitle from '../components/PageTitle.vue'
import LoadState from '../components/LoadState.vue'
const {catalog,loading,error,reload}=useCatalog()
function oldDownload(){exportTsv('NascentAtlas_93_catalog_original.tsv',Object.keys(catalog.value.older_catalog.rows[0]).map(key=>({key,label:key})),catalog.value.older_catalog.rows)}
function manifest(){const c=catalog.value;downloadBlob('NascentAtlas_catalog105_manifest.json',JSON.stringify({release:c.release,snapshot_date:c.snapshot_date,summary:c.summary,source_hashes:c.source_hashes,metric:c.metric,limitations:c.limitations},null,2))}
</script>
<template><PageTitle eyebrow="DATA DOWNLOAD" title="Bring the data into your analysis" description="Download catalogs and provenance while retaining original aliases, assays and review status."/><LoadState :loading="loading" :error="error" @retry="reload"><template v-if="catalog"><div class="release-card"><div><p class="eyebrow">CURRENT CATALOG SNAPSHOT</p><h2>105-profile catalog</h2><p>{{ catalog.snapshot_date }} · {{ catalog.summary.studies }} GSEs · Pending review</p></div><span class="status-tag">Draft release</span></div><div class="download-grid"><section class="panel download-card"><FileSpreadsheet :size="26"/><h2>Profile metadata</h2><p>Source aliases, assays, GSE accessions, cell labels and antibodies for 105 records, in TSV format.</p><button class="button primary" @click="exportTsv('NascentAtlas_profiles_105.tsv',sampleColumns,catalog.profiles)"><Download :size="16"/>Download 105-profile catalog</button></section><section class="panel download-card"><FileJson :size="26"/><h2>Complete catalog JSON</h2><p>Studies, profiles, the older catalog and catalog differences for programmatic use.</p><button class="button secondary" @click="downloadBlob('NascentAtlas_catalog.json',JSON.stringify(catalog,null,2))"><Download :size="16"/>Download catalog JSON</button></section><section class="panel download-card"><FileJson :size="26"/><h2>Data provenance manifest</h2><p>Matrix SHA256 hashes, metric units, record order and limitations for verification and reproducibility.</p><button class="button secondary" @click="manifest"><Download :size="16"/>Download manifest</button></section><section class="panel download-card"><FileSpreadsheet :size="26"/><h2>Older 93-sample catalog</h2><p>Original groups, GSEs, GSM aliases and reference fields, kept separate from the 105-profile catalog.</p><button class="button secondary" @click="oldDownload"><Download :size="16"/>Download 93-sample catalog</button></section></div><section class="panel latest-panel"><div class="panel-head"><h2>Get results for your analysis</h2></div><div class="download-options"><div><h3>Single-gene log2 PI</h3><p>Filter assays, cells and antibodies on a gene page, then export the measured values.</p><RouterLink to="/genes" class="text-link">Open gene explorer →</RouterLink></div><div><h3>Study / profile subsets</h3><p>Filter by your analysis criteria, then download the corresponding metadata.</p><RouterLink to="/samples" class="text-link">Filter profiles →</RouterLink></div><div><h3>FASTQ / BAM / BigWig</h3><p>File manifests are not connected yet. Trace original studies through their GEO records.</p><a class="text-link" href="https://www.ncbi.nlm.nih.gov/geo/" target="_blank" rel="noopener">Visit NCBI GEO <ExternalLink :size="14"/></a></div></div></section></template></LoadState></template>
